$env:PYTHONIOENCODING='utf-8'; @'
import sqlite3, math, heapq, random, collections
c = sqlite3.connect(r"e:\MyProjects\Quotr\locations.db")
c.row_factory=sqlite3.Row
rows=[dict(r) for r in c.execute("select * from locations")]
L={r["city_name"]:r for r in rows}
def p(s): x,y=s.split(","); return (float(x),float(y))
D=lambda a,b: math.dist(p(L[a]["coordinate"]),p(L[b]["coordinate"]))
hubs=[n for n,r in L.items() if r["is_hub"]]
hubadj=collections.defaultdict(dict)
for r in c.execute("select hub_a,hub_b from hub_links"):
    d=D(r[0],r[1]); hubadj[r[0]][r[1]]=d; hubadj[r[1]][r[0]]=d
# hub-only APSP
def dij(src,adj):
    dist={src:0.0}; prev={}; pq=[(0.0,src)]
    while pq:
        d,u=heapq.heappop(pq)
        if d>dist.get(u,1e18): continue
        for v,w in adj[u].items():
            nd=d+w
            if nd<dist.get(v,1e18)-1e-12: dist[v]=nd; prev[v]=u; heapq.heappush(pq,(nd,v))
    return dist,prev
HD={}; HP={}
for h in hubs: HD[h],HP[h]=dij(h,hubadj)
def hubs_of(n):
    r=L[n]
    return [n] if r["is_hub"] else [x for x in r["connected_hubs"].split(";") if x]
def route(a,b):
    best=None
    for ha in hubs_of(a):
        for hb in hubs_of(b):
            if hb not in HD[ha]: continue
            d = (0 if ha==a else D(a,ha)) + HD[ha][hb] + (0 if hb==b else D(hb,b))
            # hub path
            mid=[hb]; cur=hb
            while cur!=ha: cur=HP[ha][cur]; mid.append(cur)
            mid=mid[::-1]
            path=[a]+[x for x in mid if x!=a]+([b] if b not in mid else [])
            if best is None or d<best[0]-1e-12 or (abs(d-best[0])<1e-12 and path<best[1]): best=(d,path)
    return best
for a,b in [("Shanghai","London"),("Guangzhou","Lima"),("Hue","Osh"),("Toronto","Tokyo"),("Chengdu","Split")]:
    d,path=route(a,b); print(a,"->",b,"| km",round(d,2),"| USD",round(d*0.13,2),"| legs",len(path)-1,"|",path)
random.seed(1); serv=[n for n in L if L[n]["is_hub"] or L[n]["connected_hubs"]]
legs=collections.Counter(); maxleg=None
for _ in range(800):
    a,b=random.sample(serv,2); d,path=route(a,b); legs[len(path)-1]+=1
    if maxleg is None or len(path)>maxleg[0]: maxleg=(len(path),path)
print("legs distribution:", dict(sorted(legs.items())))
print("max path:", maxleg)
# compare naive vs correct
def naive(s,t):
    adj=collections.defaultdict(dict)
    for u in hubadj:
        for v,w in hubadj[u].items(): adj[u][v]=w
    for n,r in L.items():
        if r["is_hub"]==0:
            for h in [x for x in r["connected_hubs"].split(";") if x]: adj[n][h]=D(n,h); adj[h][n]=D(n,h)
    dist,prev=dij(s,adj); path=[t]
    while path[-1]!=s: path.append(prev[path[-1]])
    return dist[t],path[::-1]
diff=0
for _ in range(300):
    a,b=random.sample(serv,2); n=naive(a,b); r=route(a,b)
    if abs(n[0]-r[0])>1e-6: diff+=1
print("naive-vs-correct differing pairs out of 300:", diff)
